  ==============================
  Phone
  ==============================
*/

.form-phone-container {
  margin-left: 10px;
}

assets.portal.css:
/*
  ==============================
  Conversations
  ==============================
*/

.container-header-conversations,
.container-header-conversation {
  text-align: left !important;
  max-width: 100% !important;
}

.container-header-conversation {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.nav-search-conversations {
  padding: 0 !important;
}

.form-control-search-wrap-conversations {
  width: 100% !important;
}

.conversations-icon-close {
  position: absolute;
  right: 1rem;
  top: 12px;
  font-size: 1.5rem;
  color: #8b97a1;
  cursor: pointer;
}

.container-status-filter {
  max-width: 100%;
  display: flex;
  margin: 25px 0;
}

.conversations-company-scope {
  margin: 16px 0 20px;
  max-width: 100%;
}

.conversations-company-scope-toggle {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none !important;
  color: inherit !important;
  cursor: pointer;
  font-size: 0.95rem;
  line-height: 1.3;
}

.conversations-company-scope-toggle:hover .conversations-company-scope-box {
  border-color: #4a90d9;
}

.conversations-company-scope-box {
  width: 18px;
  height: 18px;
  border: 2px solid #8b97a1;
  border-radius: 3px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  background-color: #ffffff;
  color: #ffffff;
  font-size: 14px;
  line-height: 1;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.conversations-company-scope-toggle-on .conversations-company-scope-box.is-checked {
  background-color: #4a90d9;
  border-color: #4a90d9;
}

.conversations-company-scope-label {
  line-height: 1.3;
  color: inherit;
}

@media only screen and (min-width: 768px) {
  .container-status-filter {
    max-width: 300px;
  }
}

.conversations-container {
  width: 100%;
  padding: 1.5rem 1rem;
}

@media only screen and (max-width: 768px) {
  .conversations-container .container-home {
    margin: 0 auto;
    padding: 0 10px;
  }
}

.conversations-container .container {
  margin: 0 auto;
}

.conversations-breadcrumb {
  display: flex;
  flex-wrap: wrap;
  margin-bottom: 30px;
}

.conversations-breadcrumbs-link {
  margin-bottom: 5px;
}

.breadcrumb-chevron-right-icon {
  margin: 0 5px;
  color: #9a9a9a;
}

.status-filter {
  cursor: pointer;
  padding: 10px;
  border: 1px solid #e3e3e3;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  text-align: center;
  color: unset !important;
}

.status-filter:first-of-type {
  border-right: none;
  border-radius: 80px 0px 0px 80px;
}

.status-filter:last-of-type {
  border-left: none;
  border-radius: 0px 80px 80px 0px;
}

.status-filter-active {
  background-color: #e3e3e3;
}

.conversations-table-wrapper {
  width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  border-radius: 12px;
  border: 1px solid #e5e7eb;
}

.conversations-table {
  width: 100%;
  border-collapse: collapse;
  border: none;
}

.conversations-table-head {
  background-color: #fff;
}

.conversations-table-th {
  padding: 12px 16px;
  text-align: left;
  font-size: 0.875rem;
  font-weight: 600;
  color: #374151;
  border-bottom: 1px solid #e5e7eb;
  white-space: nowrap;
}

.conversations-table-sort-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  text-decoration: none;
  color: inherit;
}

.conversations-table-sort-link:hover {
  color: #1d4ed8;
}

.conversations-table-sort-icon {
  font-size: 0.75rem;
  color: #6b7280;
}

.conversations-table-row {
  border-bottom: 1px solid #e5e7eb;
  transition: background-color 0.1s ease;
}

.conversations-table-row:last-child {
  border-bottom: none;
}

.conversations-table-row:hover {
  background-color: #f9fafb;
}

.conversations-table-cell {
  padding: 14px 16px;
  font-size: 0.875rem;
  color: #374151;
  vertical-align: middle;
}

.conversations-table-cell-title {
  font-weight: 500;
}

.conversations-table-link {
  color: #111827;
  text-decoration: none;
}

.conversations-table-link:hover {
  color: #1d4ed8;
  text-decoration: underline;
}

.conversations-table-cell-date {
  color: #6b7280;
  white-space: nowrap;
}

.conversations-table-cell-status {
  white-space: nowrap;
}

.conversations-list-item-status {
  border-radius: 80px;
  padding: 4px 12px;
  font-weight: 500;
  font-size: 0.8rem;
  display: inline-block;
}

.conversations-list-item-status.open {
  color: #15803d;
  background-color: #dcfce7;
}

.conversations-list-item-status.done {
  color: #6b7280;
  background-color: #f3f4f6;
}

.channel-icon-container {
  font-size: 12px;
  background-color: #fff;
  border: 1px solid #e3e3e3;
  border-radius: 50%;
  padding: 5px;
  position: relative;
  margin-right: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.conversations-empty {
  display: flex;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  padding: 20px 0 40px;
  background: rgba(244, 243, 248, 0.4);
  border-radius: 12px;
}

.conversations-empty-text {
  color: #767676;
}

/*
  ==============================
  Conversation Details
  ==============================
*/

.thread-container {
  width: 100%;
  padding-right: 24px;
}

.thread-container-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 12px 0 0;
  border: none;
  border-radius: 0;
  overflow: visible;
  background: none;
}

.thread-section {
  border: none;
}

.thread-messages-section {
  padding: 0;
}

.thread-reply-section {
  padding: 0;
}

.thread-reply-section:empty {
  display: none;
}

.thread-divider {
  display: none;
  margin: 0;
  height: 0;
  border: none;
}

.conversation-detail {
  display: flex;
  justify-content: space-between;
  width: 100%;
}

.details-container {
  width: 320px;
  border-left: 1px solid #e3e3e3;
  padding-left: 20px;
}

.details-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: #fff;
  width: 100%;
  padding: 0;
  pointer-events: none;
}

.details-title {
  font-weight: bold;
  font-size: 18px;
  font-family: "Helvetica";
  font-family: var(--headingsAndButtonsFont);
  color: #0a3355;
  color: var(--headingsColor);
}

.detail-expand-icon {
  display: none;
}

.attributes-container {
  display: flex;
  flex-direction: column;
}

.attribute-container {
  display: flex;
  flex-direction: column;
  padding: 10px 5px;
}

.attribute-label {
  color: #767676;
  font-weight: bold;
  margin-bottom: 5px;
}

@media only screen and (max-width: 768px) {
  .thread-container-content {
    margin: 0;
  }

  .details-container {
    width: 100%;
    margin: 20px auto;
    border-left: none;
    padding-left: 0;
    cursor: pointer;
  }

  .details-header {
    background-color: #fafafa;
    border-radius: 12px;
    padding: 10px;
    pointer-events: unset;
  }

  .conversation-detail {
    display: block;
  }

  .details-title {
    font-size: 12px;
  }

  .detail-expand-icon {
    display: block;
  }

  .attribute-container {
    padding: 10px;
  }

  .attributes-container.close {
    display: none;
  }

  .attributes-container.open {
    display: flex;
    flex-direction: column;
  }
}

/*
  ==============================
  Conversation Message
  ==============================
*/

.messages-container {
  overflow: auto;
  height: 500px;
  margin-bottom: 0;
  padding: 8px 0;
  border: 1px solid #e5e7eb;
  border-radius: 0;
  background-color: #ffffff;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.messages-container::-webkit-scrollbar {
  display: none;
}

.message-container {
  display: flex;
  margin: 0 20px 20px;
  overflow: visible;
}

.message-container.out {
  flex-direction: row;
}

.message-container.in {
  flex-direction: row-reverse;
}

.message-avatar {
  height: 40px;
  width: 40px;
  min-width: 40px;
  border-radius: 50%;
  flex-shrink: 0;
  overflow: hidden;
  object-fit: cover;
  margin: 0;
}

.message-avatar.message-avatar-initials {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: #e5e7eb;
  color: #4b5563;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
  user-select: none;
}

.message-avatar-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}

.message-avatar.out {
  background-color: #e5e7eb;
}

.message-avatar.in {
  background-color: #c7d2fe;
}

.message {
  display: flex;
  flex-direction: column;
  width: fit-content;
  max-width: 75%;
  overflow: hidden;
}

.message.out {
  margin-left: 10px;
}

.message.in {
  margin-right: 10px;
}

.message-bubble {
  max-width: 600px;
  min-width: 120px;
  width: 100%;
  word-break: break-word;
  padding: 8px 16px;
}

.message-bubble > div {
  word-break: break-word;
}

.message-bubble > div > div {
  background: none !important;
}

.message-bubble.out {
  background-color: #fff1f0;
  border-radius: 0 10px 10px 10px;
}

.message-bubble.in {
  background-color: #f4f3f8;
  border-radius: 10px 0 10px 10px;
}

.message-bubble img {
  max-width: 100%;
  max-height: 100%;
  object-fit: cover;
}

.message-text {
  font-size: 16px;
  font-size: var(--baseSizeFont);
  word-break: break-word;
}

.message-meta {
  width: 100%;
  font-size: 14px;
  color: #767676;
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}

.message-meta.in {
  justify-content: flex-end;
}

.message-meta.out {
  justify-content: flex-start;
}

.message-timestamp {
  margin-right: 5px;
}

.message-meta-container,
.message-icon-container {
  display: flex;
  align-items: center;
  position: relative;
}

.message-icon {
  color: #15cc70;
  font-size: 14px;
}

.message-icon.pending {
  color: #9ca3af;
}

.message-icon.failed {
  color: #ff655d;
}

.message-channel-wrapper {
  display: flex;
  align-items: center;
  font-weight: 600;
  gap: 4px;
}

.message-channel {
  display: inline-flex;
  align-items: center;
  margin-left: 0;
  color: inherit;
  line-height: 1;
  text-transform: capitalize;
}

.message-channel-wrapper .channel-icon-container {
  font-size: inherit;
  margin-right: 0;
  border: none;
  background: transparent;
  padding: 0;
  border-radius: 0;
  min-width: 0;
  position: static;
  width: auto;
  height: auto;
}

.message-channel-wrapper .channel-icon {
  font-size: 11px;
}

.messages-see-more-container {
  display: flex;
  justify-content: center;
  margin: 0 auto 12px;
}

.messages-see-more-button {
  padding: 8px;
  cursor: pointer;
}

.conversation-message-attachments-container {
  margin-top: 8px;
}

/*
  ==============================
  Conversation Reply
  ==============================
*/

.conversation-reply-container {
  border: 1px solid #e5e7eb;
  border-radius: 0;
  background-color: #ffffff;
  overflow: hidden;
}

.conversation-reply-form {
  width: 100%;
  border: none;
  padding: 16px;
  box-sizing: border-box;
  background-color: #ffffff;
}

.conversation-reply-textarea {
  margin-bottom: 0;
  background-color: #ffffff;
}

.conversation-reply-textarea textarea {
  width: 100%;
  border: none;
  resize: vertical;
  min-height: 80px;
  margin: 0;
  padding: 0;
  line-height: unset;
  background-color: #ffffff;
}

.conversation-reply-charLimit {
  margin-left: 0;
}

.conversation-reply-textarea label {
  display: none;
}

.conversation-actions-container {
  display: flex;
  align-items: center;
  width: 100%;
  justify-content: flex-end;
  margin-top: 10px;
  background-color: #ffffff;
}

.conversation-action-send-button {
  display: flex;
  align-items: center;
}

.conversation-action-send-text {
  margin-left: 10px;
}

/*
  ==============================
  Conversation Editor
  ==============================
*/
.conversation-editor-container {
  min-height: 200px;
}

.conversation-editor-attachments-container {
  border-left: 1px solid #e3e3e3;
  border-right: 1px solid #e3e3e3;
  padding: 15px 15px 0;
}

.conversation-editor-quill-container {
  padding-bottom: 40px;
  height: 160px;
}

#portal-editor {
  border-bottom: none;
  border-left: 1px solid #e3e3e3;
  border-right: 1px solid #e3e3e3;
}

.conversation-editor-actions-container {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 10px;
  padding-top: 10px;
  border-left: 1px solid #e3e3e3;
  border-right: 1px solid #e3e3e3;
  border-bottom: 1px solid #e3e3e3;
}

.conversation-action-attachment {
  margin-right: 24px;
}

.conversation-action-attachment-label {
  cursor: pointer;
}

.conversation-action-attachment-label-disabled {
  cursor: not-allowed;
}

.conversation-action-send-button {
  margin-right: 10px;
  background-color: #52aaff;
}

.conversation-editor-attachments-container
  .conversation-attachments-container-end-user {
  justify-content: flex-start;
}

/*
  ==============================
  Conversation Attachments (plural)
  ==============================
*/
.conversation-attachments-container-end-user {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  min-height: 90px;
}

.conversation-attachments-container-agent {
  display: flex;
  justify-content: flex-start;
  align-items: center;
  min-height: 90px;
}

@media only screen and (max-width: 768px) {
  .conversation-attachments-container-end-user {
    flex-direction: column;
  }

  .conversation-attachments-container-agent {
    flex-direction: column;
  }
}

/*
  ==============================
  Conversation Attachment (singular)
  ==============================
*/
@media only screen and (max-width: 768px) {
  .conversation-attachment-container {
    margin-bottom: 10px;
  }
}
.conversation-reply-form-file-attachment {
  width: 140px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 10px;
  background: #fafafa;
  border: 1px solid #e3e3e3;
  border-radius: 12px;
  padding: 10px;
  cursor: pointer;
  background-size: cover;
}

.conversation-attachment-modal-file {
  width: 400px;
  height: 300px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: #fafafa;
  padding: 10px;
  cursor: pointer;
}

.conversation-reply-form-file-attachment-delete {
  align-self: flex-end;
}

.conversation-reply-form-file-attachment-delete-icon {
  color: #767676;
  cursor: pointer;
}

.conversation-reply-form-file-attachment-wrapper-modal {
  width: 100%;
  display: flex;
  justify-content: center;
}

.conversation-reply-form-file-attachment-wrapper {
  width: 100%;
  display: flex;
}

.conversation-reply-form-file-attachment-type {
  background-color: #ff655d;
  border-radius: 6px;
  flex: 0 0 auto;
  font-size: 10px;
  font-weight: 700;
  color: white;
  padding: 5px;
}

.conversation-reply-form-file-attachment-name-wrapper {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.conversation-reply-form-file-attachment-name-modal {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-left: 4px;
  width: 100%;
}

.conversation-reply-form-file-attachment-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-left: 4px;
  width: 80px;
}

.conversation-reply-form-file-attachment-size-wrapper-modal {
  display: flex;
  justify-content: center;
}

.conversation-reply-form-file-attachment-size-wrapper {
  align-self: flex-start;
}

.conversation-reply-form-file-attachment-size-modal {
  display: inline-block;
  align-self: flex-start;
  font-size: 10px;
  margin-top: 4px;
}

.conversation-reply-form-file-attachment-size {
  display: inline-block;
  align-self: flex-start;
  font-size: 16px;
  margin-top: 4px;
}

/*
  ==============================
  Navigation
  ==============================
*/

.nav-account-container {
  position: relative;
}

.nav-account {
  display: flex;
  align-items: center;
  padding-inline-start: 20px;
  margin-inline-start: 10px;
  border-inline-start: 1px solid #efeef6;
  cursor: pointer;
}

.nav-account-name {
  margin: 0 10px;
}

.nav-account-link {
  cursor: pointer;
}

.nav-avatar {
  height: 20px;
  width: 20px;
  border-radius: 50%;
  border: 1px solid #e3e3e3;
}

.nav-account-list-container {
  position: absolute;
  display: flex;
  flex-direction: column;
  background-color: #fff;
  padding: 20px;
  width: 200px;
  right: 0;
  top: calc(100% + 1rem);
  box-shadow: 0px 2px 4px rgba(0, 0, 0, 0.08);
  border-radius: 0px 0px 12px 12px;
}

.nav-account-list-item {
  list-style: none;
  margin-bottom: 20px;
}

.nav-menu-icon {
  font-size: 22px;
}

@media only screen and (max-width: 768px) {
  .nav-avatar {
    margin-right: 10px;
  }
  .nav-account-container.desktop {
    display: none;
  }
  .nav-account-list-container {
    border: none;
    border-radius: unset;
    z-index: 1;
    position: absolute;
    width: 100vw;
    height: 100vh;
    right: -18px;
    margin-top: -0.5rem;
    box-shadow: 0 2px 6px 0 rgb(167 167 167 / 50%);
    padding: 0;
  }
  .nav-account-list-item {
    margin-bottom: 0;
  }
  .nav-account-name {
    display: none;
  }
}

/*
  ==============================
  Login
  ==============================
*/

.login-buttons-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 15px;
}

.login-buttons-form {
  padding: 20px;
  border: 2px solid #ececec;
  border-radius: 16px;
}

.login-header {
  margin-bottom: 20px;
}

.login-button {
  border: 1px solid #e3e3e3;
  border-radius: 12px;
  display: flex;
  align-items: center;
  width: 300px;
  justify-content: center;
  padding: 15px;
  margin-bottom: 15px;
}

.login-button-text {
  margin-left: 10px;
}

/*
  ==============================
  Utils
  ==============================
*/

.showInMobile {
  display: none;
}

.hideInMobile {
  display: block;
}

@media only screen and (max-width: 768px) {
  .showInMobile {
    display: block;
  }

  .hideInMobile {
    display: none;
  }
}

/*
  ==============================
  Modal (shared, generic)
  ==============================
*/
.shared-modal {
  margin: auto;
  padding: 0;
  border: 0;
}

.shared-modal-content-conversation-attachment {
  display: flex;
}

.shared-modal-title-bar {
  display: flex;
  justify-content: space-evenly;
  position: absolute;
  right: 0;
  padding-top: 10px;
  padding-right: 10px;
}

.shared-modal-action-icon {
  font-size: 24px;
  color: #767676;
  cursor: pointer;
}

.conversations-table-th-active .conversations-table-sort-link {
  color: #111827;
  font-weight: 700;
}

.conversations-table-th-active .conversations-table-sort-icon {
  color: #111827;
}

assets.styles.css:
/*

  ==============================
  Table of Contents
  ==============================

	1.0 Globals
	2.0 Icons
  3.0 Main Containers
	4.0 Buttons
	5.0 Forms
	6.0 Pages
	6.1 Homepage
	6.2 Article page
	6.3 Search page
	6.4 Category page
	6.5 404 page
	7.0 Components
	7.1 Nav
	7.2 Hero Image
	7.3 Footer
	7.4 Category Component
	7.5 Search Header
	7.6 Article Breadcrumbs
  7.7 Article Item
  7.8 Subcategory Item
  7.9 Announcement
	8.0 Utilities
*/

/* let's set up some variables */
:root {
  --headingsAndButtonsFont: "Yoto Headline", "Helvetica", sans-serif;;
  --headingBaseSizeFont: 36px;
  --bodyTextFont: "Yoto Text", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
  Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  --baseSizeFont: 16px;
  --smallTextFont: 12px;
  --headingsColor: #0a3355;
  --bodyTextColor: #222222;
  --secondaryTextColor: #576977;
  --linksColor: #0a3355;
  --linksColorLightened: #0a3355; /* keep for backwards compatibility */
  --linkTextHoverColor: #005fad;
  --primaryButtonColor: #0a3355;
  --primaryButtonColorLightened: #0a3355; /* keep for backwards compatibility */
  --primaryButtonTextColor: #ffffff;
  --primaryButtonBackgroundHoverColor: #005fad;
  --primaryButtonTextHoverColor: #ffffff;
  --primaryBackgroundPageColor: #ffffff;
  --secondaryBackgroundPageColor: #f9f9f9;
  --borderPageColor: #b2b2b2;
}

/*
  ==============================
  1.0 Globals
  ==============================
*/

* {
  box-sizing: border-box;
  margin: 0;
}

html {
  height: 100%;
  font-size: 16px;
  font-family: "Source Sans Pro", sans-serif;
  color: #222222;
  /* font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  */
  font-family: var(--bodyTextFont);
  font-size: var(--baseSizeFont);
  color: var(--bodyTextColor);
}

body {
  min-height: 100%;
  background-color: #ffffff;
  background-color: var(--primaryBackgroundPageColor);
}

a {
  text-decoration: none;
  transition: color 0.2s ease-in-out;
  color: #0a3355;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  font-size: 16px;
  color: var(--linksColor);
  font-family: var(--bodyTextFont);
  font-size: var(--baseSizeFont);
}

a:hover {
  color: #005fad; /** fallback */
  color: var(--linkTextHoverColor);
}

h1 {
  font-size: 32px;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: "Helvetica";
  font-family: var(--headingsAndButtonsFont);
}

blockquote {
  padding-left: 4rem;
  position: relative;
  margin-bottom: 2rem;
  font-style: italic;
  line-height: 1.618rem;
}

blockquote:before {
  content: "\F756";
  position: absolute;
  left: 1rem;
  color: #576977;
  font-family: "Material Design Icons";
  font-style: normal;
  font-size: 2.5rem;
  text-rendering: auto;
  line-height: inherit;
  -webkit-font-smoothing: antialiased;
}

code {
  background-color: #f9f9f9 !important;
  color: #d72b3f !important;
  font-size: 0.75rem;
  padding: 2px 3px 1px;
  white-space: normal;
}

code,
pre {
  font-family: Monaco, Menlo, Consolas, "Courier New", monospace !important;
  border: 1px solid #d8d8d8 !important; /* :\ */
  padding: 0.1rem 0.4rem;
  border-radius: 0.2rem;
  -webkit-font-variant-ligatures: none;
  font-variant-ligatures: none;
  tab-size: 4;
  -moz-tab-size: 4;
  -o-tab-size: 4;
  -webkit-tab-size: 4;
}

pre {
  background-color: #efefef;
  overflow-x: auto;
  font-size: 0.8rem;
  padding: 1.5rem;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

th,
td {
  margin: 0;
}

table tbody {
  border: 1px solid #f1f1f1;
  border-radius: 4px;
  background-color: #fefefe;
}

table tbody th,
table tbody td {
  padding: 0.5rem 0.625rem 0.625rem;
}

table tbody tr:nth-child(even) {
  background-color: #ffffff;
  background-color: var(--primaryBackgroundPageColor) !important;
}

button {
  border: none;
  border-radius: 5px;
  margin: 0;
  padding: 0;
  width: auto;
  overflow: visible;

  border-color: #0a3355;
  border-color: var(--primaryButtonColor);

  background-color: #0a3355;
  background-color: var(--primaryButtonColor);

  color: #ffffff;
  color: var(--primaryButtonTextColor);

  /* inherit font from ancestor */
  font: inherit;

  /* Normalize `line-height`. Cannot be changed from `normal` in Firefox 4+. */
  line-height: normal;

  /* Corrects font smoothing for webkit */
  -webkit-font-smoothing: inherit;
  -moz-osx-font-smoothing: inherit;

  /* Corrects inability to style clickable `input` types in iOS */
  -webkit-appearance: none;
}

/* Remove excess padding and border in Firefox 4+ */
button::-moz-focus-inner {
  border: 0;
  padding: 0;
}

button:hover,
button a:hover {
  color: #ffffff;
  color: var(--primaryButtonTextHoverColor);
  background-color: #005fad;
  background-color: var(--primaryButtonBackgroundHoverColor);
  -webkit-transition: background-color, color 500ms ease-in-out;
  -ms-transition: background-color, color 500ms ease-in-out;
  transition: background-color, color 500ms ease-in-out;
}

.svg {
  display: inline-block;
  vertical-align: middle;
  pointer-events: none;
}

/*
  ==============================
  2.0 Icons
  ==============================
*/

/*
  ==============================
  3.0 Main Containers
  ==============================
*/

.main-layout {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  overflow-y: auto;
}

.main-layout-deflection-padding {
  padding-bottom: 70px;
}

.container {
  max-width: 1440px;
  padding: 0 10px;
  width: 100%;
  z-index: 1;
}

.featured-articles-container {
  background-color: #ffffff;
  background-color: var(--primaryBackgroundPageColor);
}

.container-home {
  flex: 1 1 auto; /** IE11 needs explicit 3 values */
  margin: 1.5rem;
}

.container-contact {
  background-color: #f9f9f9;
  background-color: var(--secondaryBackgroundPageColor);
  height: 100vh;
}

.contact-wrapper {
  padding: 60px 80px !important;
  border-radius: 3px;
  box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.15);
  background-color: #ffffff;
  background-color: var(--primaryBackgroundPageColor);
}

.contact-wrapper hr {
  display: none;
}

.categories-container,
.contact-us-container {
  background-color: #f9f9f9;
  background-color: var(--secondaryBackgroundPageColor);
}

@media only screen and (max-width: 767px) {
  .container-contact {
    background-color: #ffffff;
    background-color: var(--primaryBackgroundPageColor);
  }

  .contact-wrapper {
    box-shadow: none;
    padding: 0 !important;
  }
}

@media only screen and (min-width: 768px) {
  .container-home {
    max-width: 940px;
    margin: 4rem;
  }
}

@media only screen and (min-width: 1022px) {
  .container-home {
    width: 100%;
    margin: 4rem auto;
  }
}

/*
  ==============================
  4.0 Buttons
  ==============================
*/

.btn {
  border: 1px solid transparent;
  padding: 0.675rem 0.875rem;
  text-transform: uppercase;
  font-size: 0.75rem;
  transition: color 0.2s ease-in-out, background-color 0.2s ease-in-out;
}

.btn:hover {
  cursor: pointer;
}

.btn:disabled {
  opacity: 0.65;
  pointer-events: none;
}

.btn-submit {
  font-weight: bold;
}

.btn-secondary {
  background-color: #f8fafc;
  color: #4894c8;
  border: 1px solid #e9eff4;
  border-radius: 3px;
}

.btn-icon {
  background-color: transparent;
  color: #9c9fa8;
  padding: 0.2rem;
}

.btn-icon .mdi {
  transition: color 0.2s ease-in-out;
}

.btn-icon.btn-md {
  padding: 0.25rem;
  font-size: 1.25rem;
}

.btn-icon:hover {
  background-color: #005fad;
}

.btn-icon:hover .mdi:before {
  color: #ffffff;
}

.btn-sml {
  font-size: 0.75rem;
}

a.btn {
  color: #ffffff;
}

.btn-arrow-right {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-size: 1.25rem;
}

/*
  ==============================
  5.0 Forms
  ==============================
*/

::-webkit-input-placeholder {
  color: #576977;
  color: var(--secondaryTextColor);
}
::-moz-placeholder {
  color: #576977;
  color: var(--secondaryTextColor);
}
:-ms-input-placeholder {
  color: #576977;
  color: var(--secondaryTextColor);
}

.form-control {
  border: 1px solid #b2b2b2;
  color: #576977;
  border: 1px solid var(--borderPageColor);
  color: var(--secondaryTextColor);
  border-radius: 7px;
  outline: 0;
  height: 50px;
  line-height: 50px;
  font-size: 1rem;
}

/*
  ==============================
  6.0 Pages
  ==============================
*/

/*
  ==============================
  6.1 Homepage
  ==============================
*/

.container-header {
  font-size: 21px;
  text-align: center;
  max-width: 620px;
  margin: 0 auto;
}

@media only screen and (max-width: 768px) {
  .container-header {
    max-width: 100%;
  }
}

.contact-us-button-section-container {
  padding-top: 10px;
}

.contact-us-button-wrapper {
  display: flex;
  margin: 0 auto;
}

.contact-us-button {
  background-color: #0a3355;
  color: #ffffff;
  background-color: var(--primaryButtonColor);
  color: var(--primaryButtonTextColor);
  font-weight: bold;
  padding: 15px;
  border-radius: 5px;
  position: relative;
  display: flex;
  width: max-content;
  margin: 0 auto;
}

.searchBar-primaryMessage,
.category-primaryText,
.featuredArticles-primaryText,
.contactUs-primaryText,
.conversations-primaryText {
  font-family: "Helvetica";
  font-size: 36px;
  color: #0a3355;
  font-family: var(--headingsAndButtonsFont);
  font-size: var(--headingBaseSizeFont);
  color: var(--headingsColor);
}

.searchBar-secondaryMessage,
.category-secondaryText,
.featuredArticles-secondaryText,
.contactUs-secondaryText,
.conversations-secondaryText {
  font-size: 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  color: #222222;
  font-size: var(--baseSizeFont);
  font-family: var(--bodyTextFont);
  color: var(--bodyTextColor);
}

.contactUs-ctaText {
  font-family: "Helvetica";
  font-family: var(--headingsAndButtonsFont);
}

/*
  ==============================
  6.2 Article page
  ==============================
*/
.article-title,
.category-title {
  font-weight: bold;
  padding: 15px 0;
  color: #0a3355;
  font-family: "Helvetica";
  font-size: 36px;
  color: var(--headingsColor);
  font-family: var(--headingsAndButtonsFont);
  font-size: var(--headingBaseSizeFont);
}

.article-body {
  flex: 1 1 auto;
}

.article-body-content {
  font-size: 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  color: #222222;
  font-size: var(--baseSizeFont);
  font-family: var(--bodyTextFont);
  color: var(--bodyTextColor);
}

.article-header {
  display: flex;
  align-items: center;
  padding: 25px 0;
}

.article-body blockquote {
  border: none;
  padding-left: 4em;
  color: #222222;
  color: var(--bodyTextColor);
}

body[dir="rtl"] blockquote {
  padding-left: initial;
  padding-right: 4em;
}

body[dir="rtl"] blockquote:before {
  left: auto;
  right: 1rem;
}

.article-body p {
  margin-bottom: 1rem;
  line-height: 1.618rem;
}

.article-body .article-updated {
  margin-bottom: 1rem;
  margin-top: 10px;
  display: inline-block;
  font-size: 14px;
  color: #576977;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  color: var(--secondaryTextColor);
  font-family: var(--bodyTextFont);
}

.article-body img.img-inline {
  margin-bottom: 0;
  display: inline-block;
}

.article-body ul,
.article-body ol {
  margin-bottom: 2rem;
}

.article-body ul ul,
.article-body ul ol,
.article-body ol ul,
.article-body ol ol {
  margin-bottom: 0;
}

.article-body ul li {
  line-height: 1.618rem;
}

.article-left {
  width: 100%;
}

.article-right {
  min-width: 150px;
  height: 100%;
  padding: 25px;
  border-radius: 3px;
  width: 100%;
  margin-left: 0;
  margin-top: 30px;
  background-color: #f9f9f9;
  background-color: var(--secondaryBackgroundPageColor);
}

@media only screen and (min-width: 768px) {
  .article-right {
    width: 150px;
    margin-left: 25px;
    margin-top: 0;
  }
}

.tag-text {
  font-weight: normal;
  text-transform: uppercase;
  font-size: 12px;
  color: #576977;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  font-size: var(--smallTextFont);
  color: var(--secondaryTextColor);
  font-family: var(--bodyTextFont);
}

.tag-wrap {
  padding: 0 !important;
  display: flex;
  flex-wrap: wrap;
  flex-direction: column;
}

.ql-align-center {
  text-align: center;
}

iframe.ql-video {
  width: 100%;
  height: 50%;
}
/* Collapsible sections (<details>/<summary>) */
.article-body details,
.article-body-content details {
  border: 1px solid var(--borderPageColor);
  border-radius: 8px;
  margin: 0 0 12px;
  padding: 0 16px;
  background-color: var(--primaryBackgroundPageColor);
}

.article-body summary,
.article-body-content summary {
  cursor: pointer;
  font-family: var(--headingsAndButtonsFont);
  font-weight: bold;
  color: var(--headingsColor);
  padding: 14px 0;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.article-body summary::-webkit-details-marker,
.article-body-content summary::-webkit-details-marker {
  display: none;
}

.article-body summary::after,
.article-body-content summary::after {
  content: "+";
  font-size: 1.4rem;
  line-height: 1;
  margin-left: 12px;
}

.article-body details[open] summary::after,
.article-body-content details[open] summary::after {
  content: "\2013"; /* en dash */
}

.article-body details[open] summary,
.article-body-content details[open] summary {
  border-bottom: 1px solid var(--borderPageColor);
  margin-bottom: 16px;
}

.article-body summary:hover,
.article-body-content summary:hover {
  color: var(--linkTextHoverColor);
}
/* Yoto fonts inside collapsibles */
.article-body summary,
.article-body-content summary {
  font-family: "Yoto Headline", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  font-weight: 900;
}

.article-body details > *:not(summary),
.article-body-content details > *:not(summary),
.article-body details p,
.article-body details li,
.article-body details a,
.article-body-content details p,
.article-body-content details li,
.article-body-content details a {
  font-family: "Yoto Text", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
/*
  ==============================
	6.3 Search page
  ==============================
*/

.search-results-number {
  color: #ffffff;
  display: block;
  font-weight: 500;
  font-family: "Helvetica";
  font-size: 36px;
  font-family: var(--headingsAndButtonsFont);
  font-size: var(--headingBaseSizeFont);
}

@media only screen and (min-width: 768px) {
  .search-results-number {
    display: inline;
  }
}

.no-results-copy {
  color: #222222;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  font-size: 16px;
  color: var(--bodyTextColor);
  font-family: var(--bodyTextFont);
  font-size: var(--baseSizeFont);
}

/*
  ==============================
  6.4 Category Page
  ==============================
*/

.category-description {
  color: #222222;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  font-size: 16px;
  color: var(--bodyTextColor);
  font-family: var(--bodyTextFont);
  font-size: var(--baseSizeFont);
  margin-bottom: 20px;
}

.link-return {
  color: #0a3355;
  color: var(--linksColor);
}

.subheader-label {
  margin: 20px auto;
  font-family: "Helvetica";
  color: #0a3355;
  font-family: var(--headingsAndButtonsFont);
  color: var(--headingsColor);
  font-size: 26px;
  font-weight: bold;
}

@media only screen and (min-width: 768px) {
  .category-col-wrap {
    display: flex;
  }

  .category-right {
    flex: 1 1 auto;
    margin: 0 auto;
  }
}

/*
  ==============================
  6.5 404 Page
  ==============================
*/

.fourOhFour-wrap {
  padding: 1rem 0 1.5rem;
  text-align: center;
}

.fourOhFour-header {
  font-size: 0.6667rem;
  font-weight: bold;
  line-height: 16px;
  text-align: center;
  text-transform: uppercase;
  padding-bottom: 0.6667rem;
  width: 140px;
  margin: 0 auto 1.333rem;
  color: #576977;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  border-bottom: 3px solid #b2b2b2;

  color: var(--secondaryTextColor);
  font-family: var(--bodyTextFont);
  border-bottom: 3px solid var(--borderPageColor);
}

.fourOhFour-icon {
  font-size: 1.5rem;
}

.fourOhFour-image {
  display: block;
  margin: 3rem auto;
  max-width: 100%;
}

.fourOhFour-subheader {
  margin-bottom: 1.333rem;
  font-family: "Helvetica";
  font-size: 36px;
  color: #0a3355;
  font-family: var(--headingsAndButtonsFont);
  font-size: var(--headingBaseSizeFont);
  color: var(--headingsColor);
}

.fourOhFour-body {
  margin-bottom: 25px;
  color: #222222;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  font-size: 16px;
  color: var(--bodyTextColor);
  font-family: var(--bodyTextFont);
  font-size: var(--baseSizeFont);
}

.fourOhFour-search {
  margin: 2.611rem auto;
  max-width: 462px;
}

@media only screen and (max-width: 767px) {
  .fourOhFour-search.form-control-search -wrap {
    margin-top: 2.611rem;
  }
}

@media only screen and (min-width: 768px) {
  .fourOhFour-subheader {
    font-size: 2rem;
  }
}

@media only screen and (min-width: 1025px) {
  .fourOhFour-wrap {
    padding: 3.444rem 9.444rem 5.556rem;
  }
}

/* 
  ==============================
  7.0 Components
  ==============================
*/

/*
  ==============================
  7.1 Nav
  ==============================
*/

.nav {
  padding: 0.5rem;
  width: 100%;
  position: relative;
  box-shadow: 0 2px 6px 0 rgba(167, 167, 167, 0.5);
  z-index: 1;
  background-color: #ffffff;
  background-color: var(--primaryBackgroundPageColor);
}

.language-select {
  /* arrows */
  background-image: linear-gradient(45deg, transparent 50%, #0a3355 50%),
    linear-gradient(135deg, #0a3355 50%, transparent 50%),
    linear-gradient(to right, #ffffff, #ffffff);
  background-image: linear-gradient(
      45deg,
      transparent 50%,
      var(--linksColor) 50%
    ),
    linear-gradient(135deg, var(--linksColor) 50%, transparent 50%),
    linear-gradient(
      to right,
      var(--primaryBackgroundPageColor),
      var(--primaryBackgroundPageColor)
    );
  background-position: calc(100% - 20px) calc(1em + 2px),
    calc(100% - 15px) calc(1em + 2px), calc(100% - 2.5em) 0.5em;
  background-size: 5px 5px, 5px 5px, 1px 1.5em;
  background-repeat: no-repeat;

  /* styling */
  display: inline-block;
  line-height: 1.5em;
  padding-block: 0.5em;
  padding-inline-start: 1em;
  padding-inline-end: 2em;
  border: none;
  background-color: #ffffff;
  color: #0a3355;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  font-size: 16px;
  width: 160px;

  background-color: var(--primaryBackgroundPageColor);
  color: var(--linksColor);
  font-family: var(--bodyTextFont);
  font-size: var(--baseSizeFont);

  /* reset */
  margin: 0 auto;
  -webkit-box-sizing: border-box;
  -moz-box-sizing: border-box;
  box-sizing: border-box;
  -webkit-appearance: none;
  -moz-appearance: none;
}

/* RTL support for language select arrows */
body[dir="rtl"] .language-select {
  background-image: linear-gradient(-45deg, transparent 50%, var(--linksColor) 50%),
    linear-gradient(-135deg, var(--linksColor) 50%, transparent 50%),
    linear-gradient(
      to right,
      var(--primaryBackgroundPageColor),
      var(--primaryBackgroundPageColor)
    );
  background-position: 20px calc(1em + 2px),
    15px calc(1em + 2px), 2.5em 0.5em;
}

@media only screen and (max-width: 768px) {
  .language-select {
    margin-top: 10px;
  }
}

.language-select::-ms-expand {
  /** hide native select arrow in IE */
  display: none;
}

.language-select:hover {
  color: #005fad; /** fallback */
  color: var(--linkTextHoverColor);

  /* arrows */
  background-image: linear-gradient(45deg, transparent 50%, #0a3355 50%),
    linear-gradient(135deg, #0a3355 50%, transparent 50%),
    linear-gradient(to right, #ffffff, #ffffff);
  background-image: linear-gradient(
      45deg,
      transparent 50%,
      var(--linkTextHoverColor) 50%
    ),
    linear-gradient(135deg, var(--linkTextHoverColor) 50%, transparent 50%),
    linear-gradient(
      to right,
      var(--primaryBackgroundPageColor),
      var(--primaryBackgroundPageColor)
    );
}

/* RTL support for language select arrows on hover */
body[dir="rtl"] .language-select:hover {
  background-image: linear-gradient(-45deg, transparent 50%, var(--linkTextHoverColor) 50%),
    linear-gradient(-135deg, var(--linkTextHoverColor) 50%, transparent 50%),
    linear-gradient(
      to right,
      var(--primaryBackgroundPageColor),
      var(--primaryBackgroundPageColor)
    );
  background-position: 20px calc(1em + 2px),
    15px calc(1em + 2px), 2.5em 0.5em;
}

